package com.pathfinder;

import com.pathfinder.model.ActivityCategory;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("pathfinder")
public interface PathfinderConfig extends Config
{
	enum AccountMode
	{
		AUTO_DETECT("Auto Detect"),
		STANDARD("Standard Account"),
		BRONZEMAN("Bronzeman Mode"),
		IRONMAN("Ironman Mode");

		private final String name;

		AccountMode(String name)
		{
			this.name = name;
		}

		@Override
		public String toString()
		{
			return name;
		}
	}

	@ConfigItem(
		keyName = "accountMode",
		name = "Account Mode",
		description = "Enables custom rules like Bronzeman mode (must unlock items organically before buying on GE)"
	)
	default AccountMode accountMode()
	{
		return AccountMode.AUTO_DETECT;
	}

	@ConfigItem(
		keyName = "defaultCategory",
		name = "Default Category",
		description = "Initial category shown when opening Pathfinder"
	)
	default ActivityCategory defaultCategory()
	{
		return ActivityCategory.ALL;
	}

	@ConfigItem(
		keyName = "preferHiddenGems",
		name = "Prioritize Hidden Gems",
		description = "Scores off-the-beaten-path minigames and alternative skilling methods higher"
	)
	default boolean preferHiddenGems()
	{
		return true;
	}
}

package com.pathfinder;

import com.google.gson.Gson;
import com.google.inject.Provides;
import com.pathfinder.engine.RecommendationEngine;
import com.pathfinder.model.AccountProfile;
import com.pathfinder.model.BankSnapshot;
import com.pathfinder.ui.PathfinderPanel;
import java.awt.image.BufferedImage;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.ItemID;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import net.runelite.api.Varbits;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.StatChanged;
import net.runelite.api.vars.AccountType;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;

@Slf4j
@PluginDescriptor(
	name = "OSRS Pathfinder",
	description = "Intelligent next-step adventure advisor, North Star goal pathfinder, and unlock discovery engine",
	tags = {"pathfinder", "quests", "goals", "suggestions", "skilling", "bossing", "gear", "bronzeman", "ironman"}
)
public class PathfinderPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private ItemManager itemManager;

	@Inject
	private ConfigManager configManager;

	@Inject
	private PathfinderConfig config;

	@Inject
	private RecommendationEngine recommendationEngine;

	@Inject
	private Gson gson;

	private PathfinderPanel panel;
	private NavigationButton navButton;
	private BankSnapshot lastBankSnapshot;

	@Override
	protected void startUp() throws Exception
	{
		log.info("Starting Pathfinder plugin...");

		panel = new PathfinderPanel(this, recommendationEngine);

		final BufferedImage icon = ImageUtil.loadImageResource(getClass(), "icon.png");

		navButton = NavigationButton.builder()
			.tooltip("Pathfinder")
			.icon(icon)
			.priority(6)
			.panel(panel)
			.build();

		clientToolbar.addNavigation(navButton);

		// Load cached profile from previous session if available
		loadCachedProfile();

		// Load cached North Star goal if available
		try
		{
			String savedGoal = configManager.getConfiguration("pathfinder", "activeNorthStar");
			if (savedGoal != null && !savedGoal.isEmpty() && panel != null)
			{
				com.pathfinder.model.NorthStarGoal goal = recommendationEngine.getActivityDatabase().resolveGoal(savedGoal);
				if (goal != null)
				{
					panel.setNorthStar(goal);
				}
			}
		}
		catch (Exception ignored)
		{
		}

		clientThread.invokeLater(() -> {
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				scanAccount();
			}
		});
	}

	@Override
	protected void shutDown() throws Exception
	{
		log.info("Stopping Pathfinder plugin...");
		clientToolbar.removeNavigation(navButton);
		panel = null;
		navButton = null;
		lastBankSnapshot = null;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			clientThread.invokeLater(this::scanAccount);
		}
	}

	@Subscribe
	public void onStatChanged(StatChanged statChanged)
	{
		if (client.getGameState() == GameState.LOGGED_IN)
		{
			clientThread.invokeLater(this::scanAccount);
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if ("pathfinder".equals(event.getGroup()))
		{
			if ("cachedProfile".equals(event.getKey()) || "activeNorthStar".equals(event.getKey()))
			{
				return;
			}
			clientThread.invokeLater(this::scanAccount);
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		int containerId = event.getContainerId();
		if (containerId == InventoryID.BANK.getId())
		{
			ItemContainer bankContainer = event.getItemContainer();
			if (bankContainer != null)
			{
				processBankSnapshot(bankContainer);
				scanAccount();
			}
		}
		else if (containerId == InventoryID.INVENTORY.getId() || containerId == InventoryID.EQUIPMENT.getId())
		{
			clientThread.invokeLater(this::scanAccount);
		}
	}

	private void processBankSnapshot(ItemContainer bankContainer)
	{
		long coins = 0;
		long platinumTokens = 0;
		long estimatedTotal = 0;
		Set<Integer> ownedItemIds = new HashSet<>();

		for (Item item : bankContainer.getItems())
		{
			if (item == null || item.getId() <= 0)
			{
				continue;
			}

			int id = item.getId();
			int canonicalId = itemManager.canonicalize(id);
			int qty = item.getQuantity();

			ownedItemIds.add(id);
			ownedItemIds.add(canonicalId);

			if (canonicalId == ItemID.COINS_995 || id == ItemID.COINS_995)
			{
				coins += qty;
			}
			else if (canonicalId == ItemID.PLATINUM_TOKEN || id == ItemID.PLATINUM_TOKEN)
			{
				platinumTokens += qty;
			}

			long price = itemManager.getItemPrice(canonicalId);
			if (price <= 0)
			{
				price = itemManager.getItemPrice(id);
			}
			estimatedTotal += (price * qty);
		}

		long liquidCash = coins + (platinumTokens * 1000L);

		lastBankSnapshot = BankSnapshot.builder()
			.coins(coins)
			.platinumTokens(platinumTokens)
			.totalLiquidCash(liquidCash)
			.estimatedTotalValue(estimatedTotal)
			.ownedItemIds(ownedItemIds)
			.timestamp(System.currentTimeMillis())
			.build();

		log.debug("Pathfinder bank scanned: Cash {}, Bank Total {}, Items {}", liquidCash, estimatedTotal, ownedItemIds.size());
	}

	public void requestAccountScan()
	{
		clientThread.invokeLater(this::scanAccount);
	}

	private void scanAccount()
	{
		if (client.getGameState() != GameState.LOGGED_IN || client.getLocalPlayer() == null)
		{
			return;
		}

		String username = client.getLocalPlayer().getName();
		if (username == null || username.trim().isEmpty())
		{
			return;
		}

		Map<Skill, Integer> skills = new HashMap<>();
		int totalLevel = 0;
		for (Skill skill : Skill.values())
		{
			int level = client.getRealSkillLevel(skill);
			skills.put(skill, level);
			totalLevel += level;
		}

		// Don't save uninitialized skill sets (fresh accounts have min total level ~32)
		if (totalLevel < 32)
		{
			return;
		}

		int combatLevel = client.getLocalPlayer().getCombatLevel();

		AccountType accountType = client.getAccountType();

		// Account restriction modes (Standard, Ironman, Bronzeman)
		boolean isIronman = false;
		boolean isBronzeman = false;

		PathfinderConfig.AccountMode mode = config.accountMode();
		if (mode == PathfinderConfig.AccountMode.BRONZEMAN)
		{
			isBronzeman = true;
		}
		else if (mode == PathfinderConfig.AccountMode.IRONMAN)
		{
			isIronman = true;
		}
		else if (mode == PathfinderConfig.AccountMode.STANDARD)
		{
			isIronman = false;
			isBronzeman = false;
		}
		else // AUTO_DETECT
		{
			isIronman = accountType != null && accountType.isIronman();
			// Auto-detect Bronzeman if user has bronzeman plugin configuration
			String bmConfig = configManager.getConfiguration("bronzemanmode", "unlockedItems");
			if (bmConfig == null)
			{
				bmConfig = configManager.getConfiguration("anotherbronzemanmode", "unlockedItems");
			}
			if (bmConfig != null && !bmConfig.isEmpty())
			{
				isBronzeman = true;
			}
		}

		// Read Bronzeman unlocked items from config
		Set<Integer> unlockedItemIds = new HashSet<>();
		readBronzemanUnlocks("bronzemanmode", unlockedItemIds);
		readBronzemanUnlocks("anotherbronzemanmode", unlockedItemIds);

		Set<String> completedQuests = new HashSet<>();
		for (Quest quest : Quest.values())
		{
			try
			{
				if (quest.getState(client) == QuestState.FINISHED)
				{
					completedQuests.add(quest.getName());
				}
			}
			catch (Exception e)
			{
				// Ignored
			}
		}

		// Inventory & equipment items
		BankSnapshot snapshot = lastBankSnapshot;
		Set<Integer> allOwned = new HashSet<>();
		if (snapshot != null)
		{
			allOwned.addAll(snapshot.getOwnedItemIds());
		}
		addItemsFromContainer(InventoryID.INVENTORY, allOwned);
		addItemsFromContainer(InventoryID.EQUIPMENT, allOwned);

		if (snapshot != null)
		{
			snapshot = BankSnapshot.builder()
				.coins(snapshot.getCoins())
				.platinumTokens(snapshot.getPlatinumTokens())
				.totalLiquidCash(snapshot.getTotalLiquidCash())
				.estimatedTotalValue(snapshot.getEstimatedTotalValue())
				.ownedItemIds(allOwned)
				.timestamp(snapshot.getTimestamp())
				.build();
		}
		else if (!allOwned.isEmpty())
		{
			snapshot = BankSnapshot.builder()
				.ownedItemIds(allOwned)
				.timestamp(System.currentTimeMillis())
				.build();
		}

		// In Bronzeman mode, any item ever found in bank/inventory counts as unlocked
		unlockedItemIds.addAll(allOwned);

		Set<String> completedDiaries = new HashSet<>();
		try
		{
			if (client.getVarbitValue(Varbits.DIARY_ARDOUGNE_EASY) == 1) completedDiaries.add("ardougne-easy-diary");
			if (client.getVarbitValue(Varbits.DIARY_VARROCK_MEDIUM) == 1) completedDiaries.add("varrock-medium-diary");
		}
		catch (Exception ignored)
		{
		}

		AccountProfile profile = AccountProfile.builder()
			.username(username)
			.cachedTimestamp(System.currentTimeMillis())
			.combatLevel(combatLevel)
			.totalLevel(totalLevel)
			.isIronman(isIronman)
			.isBronzeman(isBronzeman)
			.skills(skills)
			.completedQuests(completedQuests)
			.completedDiaries(completedDiaries)
			.unlockedItemIds(unlockedItemIds)
			.bankSnapshot(snapshot)
			.build();

		saveCachedProfile(profile);

		if (panel != null)
		{
			panel.updateProfile(profile);
		}
	}

	public boolean isClientLoggedIn()
	{
		return client != null && client.getGameState() == GameState.LOGGED_IN;
	}

	public ConfigManager getConfigManager()
	{
		return configManager;
	}

	private void saveCachedProfile(AccountProfile profile)
	{
		try
		{
			String json = gson.toJson(profile);
			configManager.setConfiguration("pathfinder", "cachedProfile", json);
			log.debug("Saved cached Pathfinder profile for {}", profile.getUsername());
		}
		catch (Exception e)
		{
			log.error("Failed to save cached profile", e);
		}
	}

	private void loadCachedProfile()
	{
		try
		{
			String json = configManager.getConfiguration("pathfinder", "cachedProfile");
			if (json != null && !json.isEmpty())
			{
				AccountProfile profile = gson.fromJson(json, AccountProfile.class);
				if (profile != null && panel != null)
				{
					log.info("Loaded cached Pathfinder profile for {} (Combat {})",
						profile.getUsername(), profile.getCombatLevel());
					panel.updateProfile(profile);
				}
			}
		}
		catch (Exception e)
		{
			log.error("Failed to load cached profile", e);
		}
	}

	private void readBronzemanUnlocks(String group, Set<Integer> targetSet)
	{
		String data = configManager.getConfiguration(group, "unlockedItems");
		if (data != null && !data.isEmpty())
		{
			for (String part : data.split("[,;\\s]+"))
			{
				try
				{
					targetSet.add(Integer.parseInt(part.trim()));
				}
				catch (NumberFormatException ignored)
				{
				}
			}
		}
	}

	private void addItemsFromContainer(InventoryID containerId, Set<Integer> targetSet)
	{
		ItemContainer container = client.getItemContainer(containerId);
		if (container != null)
		{
			for (Item item : container.getItems())
			{
				if (item != null && item.getId() > 0)
				{
					targetSet.add(item.getId());
					targetSet.add(itemManager.canonicalize(item.getId()));
				}
			}
		}
	}

	@Provides
	PathfinderConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(PathfinderConfig.class);
	}
}

package com.pathfinder.engine;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.pathfinder.model.Activity;
import com.pathfinder.model.ActivityCategory;
import com.pathfinder.model.BossCheckpoint;
import com.pathfinder.model.CombatCheckpoint;
import com.pathfinder.model.GearUpgrade;
import com.pathfinder.model.NorthStarGoal;
import com.pathfinder.model.SkillRequirement;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Skill;

@Slf4j
@Singleton
public class ActivityDatabase
{
	private final List<Activity> activities = new ArrayList<>();
	private final List<GearUpgrade> gearUpgrades = new ArrayList<>();
	private final List<CombatCheckpoint> combatCheckpoints = new ArrayList<>();
	private final List<BossCheckpoint> bossCheckpoints = new ArrayList<>();
	private final Gson gson;

	@Inject
	public ActivityDatabase(Gson gson)
	{
		this.gson = gson;
		loadActivities();
		loadGearUpgrades();
		loadCombatCheckpoints();
		loadBossCheckpoints();

		if (activities.isEmpty())
		{
			log.warn("Pathfinder fallback: initializing hardcoded activities");
			initFallbackActivities();
		}
	}

	public List<Activity> getAllActivities()
	{
		return Collections.unmodifiableList(activities);
	}

	public List<GearUpgrade> getGearUpgrades()
	{
		return Collections.unmodifiableList(gearUpgrades);
	}

	public List<CombatCheckpoint> getCombatCheckpoints()
	{
		return Collections.unmodifiableList(combatCheckpoints);
	}

	public List<BossCheckpoint> getBossCheckpoints()
	{
		return Collections.unmodifiableList(bossCheckpoints);
	}

	public Activity getActivity(String id)
	{
		for (Activity a : activities)
		{
			if (a.getId().equalsIgnoreCase(id))
			{
				return a;
			}
		}
		return null;
	}

	public GearUpgrade getGearUpgrade(String id)
	{
		for (GearUpgrade g : gearUpgrades)
		{
			if (g.getId().equalsIgnoreCase(id))
			{
				return g;
			}
		}
		return null;
	}

	public GearUpgrade getGearUpgradeByItemId(int itemId)
	{
		for (GearUpgrade g : gearUpgrades)
		{
			if (g.getItemId() == itemId)
			{
				return g;
			}
		}
		return null;
	}

	public CombatCheckpoint getCombatCheckpoint(String id)
	{
		for (CombatCheckpoint cp : combatCheckpoints)
		{
			if (cp.getId().equalsIgnoreCase(id))
			{
				return cp;
			}
		}
		return null;
	}

	public BossCheckpoint getBossCheckpoint(String id)
	{
		for (BossCheckpoint bp : bossCheckpoints)
		{
			if (bp.getId().equalsIgnoreCase(id))
			{
				return bp;
			}
		}
		return null;
	}

	public NorthStarGoal resolveGoal(String goalId)
	{
		if (goalId == null || goalId.trim().isEmpty() || "none".equalsIgnoreCase(goalId))
		{
			return null;
		}

		// 1. Check Combat Checkpoints
		CombatCheckpoint cp = getCombatCheckpoint(goalId);
		if (cp != null)
		{
			return createGoalFromCombatCheckpoint(cp);
		}

		// 2. Check Boss Checkpoints
		BossCheckpoint bp = getBossCheckpoint(goalId);
		if (bp != null)
		{
			return createGoalFromBossCheckpoint(bp);
		}

		// 3. Check Activities (quests, minigames, skilling, etc.)
		String cleanActId = goalId.startsWith("activity-") ? goalId.substring("activity-".length()) : goalId;
		Activity a = getActivity(cleanActId);
		if (a == null)
		{
			a = getActivity(goalId);
		}
		if (a != null)
		{
			return createGoalFromActivity(a);
		}

		// 4. Check Gear Upgrades
		String cleanGearId = goalId.startsWith("gear-") ? goalId.substring("gear-".length()) : goalId;
		GearUpgrade g = getGearUpgrade(cleanGearId);
		if (g == null)
		{
			g = getGearUpgrade(goalId);
		}
		if (g != null)
		{
			return createGoalFromGear(g);
		}

		// 5. Fallback search by title
		for (Activity act : activities)
		{
			if (act.getTitle().equalsIgnoreCase(goalId))
			{
				return createGoalFromActivity(act);
			}
		}

		return null;
	}

	public NorthStarGoal createGoalFromActivity(Activity activity)
	{
		Map<Skill, Integer> targetSkills = new HashMap<>();
		for (SkillRequirement sr : activity.getSkillRequirements())
		{
			targetSkills.put(sr.getSkill(), sr.getLevel());
		}

		String cat = activity.getCategory() == ActivityCategory.QUEST ? "Quest Goal"
			: activity.getCategory() == ActivityCategory.BOSSING ? "Boss Encounter"
			: activity.getCategory() == ActivityCategory.DIARY ? "Achievement Diary"
			: "Milestone Goal";

		return NorthStarGoal.builder()
			.id("activity-" + activity.getId())
			.title(activity.getTitle())
			.type(NorthStarGoal.GoalType.ACTIVITY)
			.category(cat)
			.description(activity.getDescription())
			.highlight(activity.getUnlockHighlight())
			.wikiUrl(activity.getSafeWikiUrl())
			.targetCombat(activity.getRecommendedCombat())
			.targetSkills(targetSkills)
			.prerequisiteQuests(activity.getQuestRequirements())
			.build();
	}

	public NorthStarGoal createGoalFromGear(GearUpgrade gear)
	{
		Map<Skill, Integer> targetSkills = new HashMap<>();
		for (SkillRequirement sr : gear.getSkillReqs())
		{
			targetSkills.put(sr.getSkill(), sr.getLevel());
		}
		for (SkillRequirement sr : gear.getOrganicSkillReqs())
		{
			Integer existing = targetSkills.get(sr.getSkill());
			if (existing == null || sr.getLevel() > existing)
			{
				targetSkills.put(sr.getSkill(), sr.getLevel());
			}
		}

		List<String> quests = gear.getQuestReq() != null && !gear.getQuestReq().isEmpty()
			? Collections.singletonList(gear.getQuestReq())
			: Collections.emptyList();

		return NorthStarGoal.builder()
			.id("gear-" + gear.getId())
			.title(gear.getName())
			.type(NorthStarGoal.GoalType.GEAR_ITEM)
			.category("Gear Upgrade (" + gear.getSlot() + ")")
			.description(gear.getHighlight())
			.highlight("Slot: " + gear.getSlot() + " | " + gear.getTier() + " Tier")
			.wikiUrl(gear.getWikiUrl())
			.targetCombat(gear.getRecommendedCombat())
			.targetSkills(targetSkills)
			.prerequisiteQuests(quests)
			.requiredItemIds(Collections.singletonList(gear.getItemId()))
			.requiredItemNames(Collections.singletonList(gear.getName()))
			.build();
	}

	public NorthStarGoal createGoalFromCombatCheckpoint(CombatCheckpoint cp)
	{
		return NorthStarGoal.builder()
			.id(cp.getId())
			.title(cp.getName())
			.type(NorthStarGoal.GoalType.COMBAT_CHECKPOINT)
			.category(cp.getStyle() + " Checkpoint (" + cp.getTier() + ")")
			.description(cp.getDescription())
			.highlight(cp.getHighlight())
			.targetCombat(cp.getRecommendedCombat())
			.targetSkills(cp.getRecommendedSkills())
			.requiredItemIds(cp.getCoreItemIds())
			.requiredItemNames(cp.getCoreItemNames())
			.build();
	}

	public NorthStarGoal createGoalFromBossCheckpoint(BossCheckpoint bp)
	{
		return NorthStarGoal.builder()
			.id(bp.getId())
			.title(bp.getBossName())
			.type(NorthStarGoal.GoalType.BOSS_CHECKPOINT)
			.category("Boss Readiness (" + bp.getTier() + ")")
			.description(bp.getDescription())
			.highlight(bp.getUnlockHighlight())
			.wikiUrl(bp.getWikiUrl())
			.targetCombat(bp.getRecommendedCombat())
			.targetSkills(bp.getRecommendedSkills())
			.prerequisiteQuests(bp.getPrerequisiteQuests())
			.requiredItemIds(bp.getRecommendedItemIds())
			.requiredItemNames(bp.getRecommendedItemNames())
			.build();
	}

	private void loadActivities()
	{
		try (InputStream is = getClass().getResourceAsStream("/com/pathfinder/activities.json"))
		{
			if (is == null)
			{
				log.warn("activities.json not found in resources");
				return;
			}

			try (InputStreamReader reader = new InputStreamReader(is, StandardCharsets.UTF_8))
			{
				JsonArray array = gson.fromJson(reader, JsonArray.class);
				for (JsonElement el : array)
				{
					JsonObject obj = el.getAsJsonObject();
					Activity.ActivityBuilder builder = Activity.builder()
						.id(obj.get("id").getAsString())
						.title(obj.get("title").getAsString())
						.wikiUrl(obj.has("wikiUrl") ? obj.get("wikiUrl").getAsString() : "")
						.category(ActivityCategory.valueOf(obj.get("category").getAsString()))
						.description(obj.get("description").getAsString())
						.unlockHighlight(obj.get("unlockHighlight").getAsString())
						.recommendedCombat(obj.get("recommendedCombat").getAsInt())
						.ironmanFriendly(obj.get("ironmanFriendly").getAsBoolean())
						.hiddenGem(obj.get("hiddenGem").getAsBoolean());

					List<SkillRequirement> skillReqs = new ArrayList<>();
					if (obj.has("skillRequirements"))
					{
						for (JsonElement reqEl : obj.getAsJsonArray("skillRequirements"))
						{
							JsonObject reqObj = reqEl.getAsJsonObject();
							Skill skill = Skill.valueOf(reqObj.get("skill").getAsString());
							int level = reqObj.get("level").getAsInt();
							skillReqs.add(new SkillRequirement(skill, level));
						}
					}
					builder.skillRequirements(skillReqs);

					List<String> questReqs = new ArrayList<>();
					if (obj.has("questRequirements"))
					{
						for (JsonElement qEl : obj.getAsJsonArray("questRequirements"))
						{
							questReqs.add(qEl.getAsString());
						}
					}
					builder.questRequirements(questReqs);

					List<String> tags = new ArrayList<>();
					if (obj.has("tags"))
					{
						for (JsonElement tEl : obj.getAsJsonArray("tags"))
						{
							tags.add(tEl.getAsString());
						}
					}
					builder.tags(tags);

					// Infer or parse trained skills
					List<Skill> trainedSkills = new ArrayList<>();
					if (obj.has("trainedSkills"))
					{
						for (JsonElement tsEl : obj.getAsJsonArray("trainedSkills"))
						{
							try
							{
								trainedSkills.add(Skill.valueOf(tsEl.getAsString().toUpperCase()));
							}
							catch (Exception ignored) {}
						}
					}
					else
					{
						// Automatically map from tags and skill requirements
						for (String tag : tags)
						{
							for (Skill s : Skill.values())
							{
								if (tag.equalsIgnoreCase(s.getName()) && !trainedSkills.contains(s))
								{
									trainedSkills.add(s);
								}
							}
						}
						for (SkillRequirement sr : skillReqs)
						{
							if (!trainedSkills.contains(sr.getSkill()))
							{
								trainedSkills.add(sr.getSkill());
							}
						}
					}
					builder.trainedSkills(trainedSkills);

					activities.add(builder.build());
				}
				log.info("Loaded {} activities from activities.json", activities.size());
			}
		}
		catch (Exception e)
		{
			log.error("Failed to load activities.json", e);
		}
	}

