		int targetLevel;
		int levelsRemaining;
	}

	@Value
	@Builder
	public static class ItemGap
	{
		int itemId;
		String itemName;
	}

	NorthStarGoal goal;
	boolean isFullyReady;
	int totalRequirements;
	int satisfiedRequirements;
