	@Test
	public void testPathwayActivitiesSurfacedAndPrioritized()
	{
		// Construction is 40, Song of the Elves needs 70
		Map<Skill, Integer> skills = new HashMap<>();
		for (Skill s : Skill.values())
		{
			skills.put(s, 70);
		}
		skills.put(Skill.CONSTRUCTION, 40);

